Problem:
A nearby lake is frequently artificially seeded with trout for local fishermen. The trout are transported using either large trucks or by boat. Transporting using large trucks can take 2000 trout and costs $300 per trip. Transporting with boat can take 1200 trout and costs $100 per trip. Since boats take extra preparation, at least 75% of trips should be by large trucks. Additionally, there can be at most 5 trips by boat. If at least 7000 trout need to be seeded into the nearby lake, how many of each type of trip should be taken to minimize the total cost?

Model and facts:
{
 "model": {
  "variables": [
   {
    "name": "large truck trips",
    "lower": 0.0,
    "upper": null,
    "integer": true
   },
   {
    "name": "boat trips",
    "lower": 0.0,
    "upper": null,
    "integer": true
   }
  ],
  "objective": {
   "sense": "min",
   "terms": [
    {
     "var": "large truck trips",
     "coef": 300.0
    },
    {
     "var": "boat trips",
     "coef": 100.0
    }
   ]
  },
  "constraints": [
   {
    "name": "demand",
    "terms": [
     {
      "var": "large truck trips",
      "coef": 2000.0
     },
     {
      "var": "boat trips",
      "coef": 1200.0
     }
    ],
    "sense": ">=",
    "rhs": 7000.0
   },
   {
    "name": "truck_share",
    "terms": [
     {
      "var": "large truck trips",
      "coef": 0.25
     },
     {
      "var": "boat trips",
      "coef": -0.75
     }
    ],
    "sense": ">=",
    "rhs": 0.0
   },
   {
    "name": "boat_limit",
    "terms": [
     {
      "var": "boat trips",
      "coef": 1.0
     }
    ],
    "sense": "<=",
    "rhs": 5.0
   }
  ]
 },
 "facts": {
  "objective": 1000.0,
  "values": {
   "large truck trips": 3.0,
   "boat trips": 1.0
  },
  "binding": [
   "truck_share"
  ],
  "slack": {
   "demand": 200.0,
   "truck_share": 0.0,
   "boat_limit": 4.0
  },
  "shadow_prices": null,
  "limits": {
   "demand": {
    "dropped_improves": true,
    "loosened_improves": false
   },
   "truck_share": {
    "dropped_improves": true,
    "loosened_improves": false
   },
   "boat_limit": {
    "dropped_improves": false,
    "loosened_improves": false
   }
  }
 }
}
